  var dl = Math.sqrt(dd);
  if (dl < 1e-6) { dx2 = 0; dy2 = 1; dz2 = 0; dl = 1; }
  return { nx: dx2 / dl, ny: dy2 / dl, nz: dz2 / dl, depth: rr - dl };
